import os, re, json, glob

def load_grids():
    """Load all grids from this instance's conversation so far."""
    rlm_dir = os.environ.get('RLM_SESSION_DIR')
    if not rlm_dir:
        return {}

    d = os.path.join(
        os.path.dirname(rlm_dir), '..', '..', 'sessions'
    )
    session_file = os.path.join(d, os.path.basename(rlm_dir) + '.jsonl')

    if os.path.exists(session_file):
        with open(session_file, 'r') as f:
            content = f.read()

        grids = {}
        for match in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', content):
            k = match[1]
            h, w = int(match[2]), int(match[3])
            lines = content[match.end():].split('\n')[:h]
            parsed = [[int(x) for x in line.split()] for line in lines]
            if k not in grids and all(len(row) == w and all(x.isdigit() for x in row) for row in parsed):
                grids[k] = parsed

        return grids
    return {}

